import vtk

from ..types import Scalar, Vector, SymmetricTensor, AsymmetricTensor
from .node import RootNode, ModuleSummary, Guardrail, raise_on_tool_param_false
from topopilot.config import correctness_checks_on
from paraview.simple import *

def type_guardrail(type_name : str):
    return Guardrail(f"ensure that the user actually wants a {type_name} before loading (if it is not clear from the context)",
                    f"explicitly_specified_{type_name.replace(" ", "_")}",
                    f"did the user explicitly specify that they are loading a {type_name}",
                    raise_on_tool_param_false(
                        f"Cannot create node. The user did not explicitly specify that they are loading a {type_name}."
                    ))

class LoadScalarField(RootNode):

    def __init__(self, load_path : str, arrayName : str = ""):
        """
        Loads a scalar field from a file given at load_path.

        Args:
            load_path: The path to the scalar field that should be loaded.
            arrayName: The name of the array that should be loaded for the scalar field. If this is
                       left empty and the file only has one array, that single array will be used for the
                       scalar field.
        """

        super().__init__(load_path, Scalar, locals(), [arrayName])

        reader = vtk.vtkXMLImageDataReader()
        reader.SetFileName(self.check_file)
        reader.Update()

        image = reader.GetOutput()
        pd = image.GetPointData()
        numArrays = pd.GetNumberOfArrays()

        # if correctness_checks_on():
        if numArrays == 0:
            raise ValueError(f"File {load_path} has no arrays")
        elif numArrays == 1 and arrayName == "":
            arrayName = pd.GetArrayName(0)
        elif numArrays > 1:
            if arrayName == "":
                raise ValueError(f"The file {load_path} has multiple arrays and the user did not specify one. The user"\
                                " must specify if the data is scalar, vector, symmetric tensor, or asymmetric tensor data"\
                                " and which arrays they want to load.")

            if not pd.HasArray(arrayName):
                raise ValueError(f"File {load_path} has no array '{arrayName}'")

        self.arrayName = arrayName
        self._commit()

    @classmethod
    def chat_description(cls):
        return "queued loading scalar field"

    @classmethod
    def description(cls):
        return 'Loads a scalar field from a file given at load_path.'

    @classmethod
    def param_descriptions(cls):
        return {'load_path': 'The path to the scalar field that should be loaded. Time varying data is loaded by specifying a directory.',
         'arrayName': 'The name of the array that should be loaded for the scalar field. If '
                      'this is left empty and the file only has one array, that single array '
                      'will be used for the scalar field.'}

    def _evaluation_logic(self, filename):
        vti = XMLImageDataReader(FileName=[filename])
        vti.PointArrayStatus = [self.arrayName]
        vti.TimeArray = 'None'

        renameArrays = RenameArrays(Input=vti)
        renameArrays.PointArrays = [self.arrayName, 'Scalars_']
        return Scalar(renameArrays)

class LoadVectorField(RootNode):

    def __init__(self, load_path : str, u_array_name : str, v_array_name : str):
        """
        Loads a vector field from a file given at load_path.

        Args:
            load_path: The path to the vector field that should be loaded.
            u_array_name: The name of the array storing the x component of the vectors.
            v_array_name: The name of the array storing the y component of the vectors.
        """

        super().__init__(load_path, Vector, locals(), [u_array_name, v_array_name])

        reader = vtk.vtkXMLImageDataReader()
        reader.SetFileName(self.check_file)
        reader.Update()

        image = reader.GetOutput()
        pd = image.GetPointData()
        numArrays = pd.GetNumberOfArrays()

        if correctness_checks_on():
            if numArrays < 2:
                raise ValueError(f"File {load_path} has only {numArrays} arrays, but needs at least 2 to load a vector field.")

            if not pd.HasArray(u_array_name):
                raise ValueError(f"File {load_path} has no array '{u_array_name}'")

            if not pd.HasArray(v_array_name):
                raise ValueError(f"File {load_path} has no array '{v_array_name}'")

            if len(self.dimensions) > 2 and self.dimensions[2] != 1:
                raise ValueError(f"File {load_path} is three dimensional but currently only 2D vector fields are supported.")

        self.u_array_name = u_array_name
        self.v_array_name = v_array_name
        self._commit()

    @classmethod
    def chat_description(cls):
        return "queued loading vector field"

    @classmethod
    def description(cls):
        return 'Loads a vector field from a file given at load_path.'

    @classmethod
    def param_descriptions(cls):
        return {'load_path': 'The path to the vector field that should be loaded. Time varying data is loaded by specifying a directory.',
         'u_array_name': 'The name of the array storing the x component of the vectors.',
         'v_array_name': 'The name of the array storing the y component of the vectors.'}

    def _evaluation_logic(self, filename):
        vti = XMLImageDataReader(FileName=[filename])
        vti.PointArrayStatus = [self.u_array_name, self.v_array_name]
        vti.TimeArray = 'None'

        renameArrays = RenameArrays(Input=vti)
        renameArrays.PointArrays = [self.u_array_name, 'u', self.v_array_name, 'v']
        return Vector(renameArrays)

